def _permisos() -> None:
    con = op.get_bind()
    con.execute(
        sa.text(
            "INSERT INTO roles (nombre, descripcion, activo, inicio) SELECT CAST(:n AS varchar), CAST(:d AS text), true, 'personal' "
            "WHERE NOT EXISTS (SELECT 1 FROM roles WHERE nombre = CAST(:n AS varchar))"
        ),
        {"n": ROL_PERSONAL, "d": "Encargada/o de personal: asistencias, horarios, justificativos, licencias y comisiones."},
    )
    PERMISOS[ROL_PERSONAL] = [("personal", "consultar", "todos"), ("personal", "administrar", "todos"), ("recursos", "consultar", "todos")]
    for rol, lista in PERMISOS.items():
        for modulo, accion, alcance in lista:
            con.execute(
                sa.text(
                    "INSERT INTO roles_permisos (rol_id, modulo, accion, alcance) "
                    "SELECT r.id, CAST(:m AS varchar), CAST(:a AS varchar), CAST(:al AS varchar) FROM roles r WHERE r.nombre = :rol "
                    "AND NOT EXISTS (SELECT 1 FROM roles_permisos p WHERE p.rol_id = r.id AND p.modulo = CAST(:m AS varchar) "
                    "AND p.accion = CAST(:a AS varchar))"
                ),
                {"rol": rol, "m": modulo, "a": accion, "al": alcance},
            )


